import{_ as t,o,c as a,a4 as r}from"./chunks/framework.DpieW3qv.js";const p=JSON.parse('{"title":"BaseUseCase Extraction (Follow-up Refactor)","description":"","frontmatter":{},"headers":[],"relativePath":"future/BASE-USECASE-EXTRACTION.md","filePath":"future/BASE-USECASE-EXTRACTION.md","lastUpdated":null}'),d={name:"future/BASE-USECASE-EXTRACTION.md"};function s(i,e,c,l,n,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="baseusecase-extraction-follow-up-refactor" tabindex="-1">BaseUseCase Extraction (Follow-up Refactor) <a class="header-anchor" href="#baseusecase-extraction-follow-up-refactor" aria-label="Permalink to &quot;BaseUseCase Extraction (Follow-up Refactor)&quot;">​</a></h1><blockquote><p><strong>Status</strong>: Follow-up (post-launch)<br><strong>Priority</strong>: Low — not blocking launch<br><strong>Estimated Effort</strong>: 1 day</p></blockquote><hr><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p><code>BaseUseCase.js</code> (678 LOC) accumulates retry, timeout, HTML diffing, and validation helpers that are not used by all subclasses. This makes it a &quot;utility god-class&quot; that is harder to test in isolation and creates implicit coupling between unrelated concerns.</p><h3 id="current-responsibilities" tabindex="-1">Current Responsibilities <a class="header-anchor" href="#current-responsibilities" aria-label="Permalink to &quot;Current Responsibilities&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Concern</th><th>Methods</th><th>Used By</th></tr></thead><tbody><tr><td>Retry / error recovery</td><td><code>safeCall</code>, <code>safeBatch</code>, <code>safeExecute</code>, <code>executeWrapped</code></td><td>All use cases</td></tr><tr><td>Timeout</td><td><code>withTimeout</code></td><td>SyncToSfcc</td></tr><tr><td>HTML diffing</td><td><code>isHtmlDifferent</code>, <code>resolveHtml</code></td><td>GenerateDevFiles, SyncToSfcc</td></tr><tr><td>Campaign validation</td><td><code>validateCampaign</code></td><td>GenerateDevFiles, SyncToSfcc</td></tr><tr><td>ExecutionTracker</td><td><code>this.tracker</code></td><td>All use cases</td></tr></tbody></table><h2 id="proposed-extraction" tabindex="-1">Proposed Extraction <a class="header-anchor" href="#proposed-extraction" aria-label="Permalink to &quot;Proposed Extraction&quot;">​</a></h2><p>Split into focused modules that can be composed via mixins or injected helpers:</p><ol><li><strong><code>RetryMixin</code></strong> — <code>safeCall</code>, <code>safeBatch</code>, <code>safeExecute</code>, <code>executeWrapped</code></li><li><strong><code>HtmlResolution</code></strong> — <code>isHtmlDifferent</code>, <code>resolveHtml</code></li><li><strong><code>ValidationHelper</code></strong> — <code>validateCampaign</code></li></ol><p><code>BaseUseCase</code> would retain only the core lifecycle: constructor, <code>this.brand</code>, <code>this.tracker</code>, and the <code>executeWrapped</code> wrapper.</p><h2 id="why-not-now" tabindex="-1">Why Not Now <a class="header-anchor" href="#why-not-now" aria-label="Permalink to &quot;Why Not Now&quot;">​</a></h2><ul><li>The current structure works correctly and is well-documented.</li><li>All subclasses pass tests as-is.</li><li>The refactor touches every use case file and needs careful test updates.</li><li>Ship-blocking and high-impact items were prioritized first.</li></ul><h2 id="when-to-do-this" tabindex="-1">When to Do This <a class="header-anchor" href="#when-to-do-this" aria-label="Permalink to &quot;When to Do This&quot;">​</a></h2><ul><li>When adding a new use case that doesn&#39;t need HTML or validation helpers.</li><li>When <code>BaseUseCase</code> grows beyond ~700 LOC.</li><li>During a dedicated maintenance sprint.</li></ul>',15)])])}const f=t(d,[["render",s]]);export{p as __pageData,f as default};
